import sys
from collections import Counter

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:n+1]]

    freq = Counter(a)
    counts = sorted(freq.values(), reverse=True)

    max_cells = 0
    best_p, best_q = 1, 1

    for p in range(1, n + 1):
        needed = p * p
        available = 0
        for c in counts:
            if c >= p:
                available += p
            else:
                available += c
            if available >= needed:
                break

        if available >= needed:
            q = available // p
            if p * q > max_cells:
                max_cells = p * q
                best_p, best_q = p, q
            elif p * q == max_cells and p < best_p:
                best_p, best_q = p, q

    p, q = best_p, best_q

    used_counts = {}
    selected = []
    for val, count in freq.items():
        take = min(count, p)
        if take > 0:
            used_counts[val] = take
            selected.extend([val] * take)

    selected.sort(key=lambda x: freq[x], reverse=True)

    grid = [[0] * q for _ in range(p)]
    idx = 0
    shift = 0

    for i in range(p):
        for j in range(q):
            grid[i][j] = selected[idx % len(selected)]
            idx += 1

    for i in range(p):
        for j in range(q, p):
            pass

    for i in range(p):
        for j in range(q - 1, -1, -1):
            if j > 0:
                grid[i][j], grid[i][j-1] = grid[i][j-1], grid[i][j]

    for i in range(p):
        row_vals = grid[i][:q]
        seen = set()
        for j in range(q):
            if row_vals[j] in seen:
                while row_vals[j] in seen:
                    row_vals[j] = grid[(i + 1) % p][j]
                    grid[(i + 1) % p][j] = row_vals[j]
            seen.add(row_vals[j])
        grid[i] = row_vals

    output = []
    output.append(str(p * q))
    output.append(f"{p} {q}")
    for row in grid:
        output.append(" ".join(map(str, row[:q])))

    print("\n".join(output))

if __name__ == "__main__":
    solve()
